					fmt.Println("added task: ", cmd.Args().First())
					return nil
				},
			},
			{
				Name:    "complete",
				Aliases: []string{"c"},
				Usage:   "complete a task on the list",
				Action: func(ctx context.Context, cmd *cli.Command) error {
					fmt.Println("completed task...", "path": "docs/v3/examples/completions/shell-completions.md", "retrieval_provenance": {"blob_sha": "8c4137e598eee8ac91e15aa38ab75775805f2ad9", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 11, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "docs/v3/examples/completions/shell-completions.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 11, "selection_score": [45, 2, 5, 5, "docs/v3/examples/completions/shell-completions.md"], "tree_discovery_succeeded": true, "tree_ref": "138d3b34001ba0ddd59f6f29474788ba3d2f8ea7", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "138d3b34001ba0ddd59f6f29474788ba3d2f8ea7"}, {"blob_sha": "e5a5fff7e5c556c07c1e99e23175e3949a3d7963", "excerpt": "---
