	subCmd := &cli.Command{Name: "mid", Commands: [...", "path": "docs/v3/path-and-walk.md", "retrieval_provenance": {"blob_sha": "8054860ef052a0d79de51ede5886c113102a9f1b", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 11, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "docs/v3/path-and-walk.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 1, "selection_score": [45, 4, 5, 3, "docs/v3/path-and-walk.md"], "tree_discovery_succeeded": true, "tree_ref": "79f8fc7a415bb2a36c2bb8b9f840d838dfb13a07", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "79f8fc7a415bb2a36c2bb8b9f840d838dfb13a07"}, {"blob_sha": "8c4137e598eee8ac91e15aa38ab75775805f2ad9", "excerpt": "---
