   {{end}}{{end}}{{if .Copyright }}
COPYRIGHT:
   {{.Copyright}}
   {{end}}{{if .Version}}
VERSION:
   {{.Version}}
   {{end}}
`

  // EXAMPLE: Replace the `HelpPrinter` func
  cli.HelpPrinter = func(w io.Writer, templ string, data interface{}) {
    fmt.Println("Ha HA.  I pwnd the help!!1")
  }

  err := cli.NewApp().Run(os.Args)
  if err != nil {
    log.Fatal(err)
  }
}
```

The default flag may be customized to something other than `-h/--help` by
setting `cli.HelpFlag`, e.g.:

<!-- {
  "args": ["&#45;&#45halp"],
  "output": "haaaaalp.*HALP"
} -->
``` go
package main

import (
  "log"
  "os"

  "github.com/urfave/cli"
)

func main() {
  cli.HelpFlag = cli.BoolFlag{
    Name: "halp, haaaaalp",
    Usage: "HALP",
    EnvVar: "SHOW_HALP,HALPPLZ",
  }

  err := cli.NewApp().Run(os.Args)
  if err != nil {
    log.Fatal(err)
  }
}
```

<!-- docs/v2/examples/generated-help-text.md @ c6f4cf7e9223793478cfcde9b8f135cc8f86e78f -->
---
tags:
  - v2
search:
  boost: 2
---

The default help flag (`-h/--help`) is defined as `cli.HelpFlag` and is checked
by the cli internals in order to print generated help text for the app, command,
or subcommand, and break execution.

#### Customization

All of the help text generation may be customized, and at multiple levels.  The
templates are exposed as variables `AppHelpTemplate`, `CommandHelpTemplate`, and
`SubcommandHelpTemplate` which may be reassigned or augmented, and full override
is possible by assigning a compatible func to the `cli.HelpPrinter` variable,
e.g.:

<!-- {
  "output": "Ha HA.  I pwnd the help!!1"
} -->
```go
package main

import (
	"fmt"
	"io"
	"os"

	"github.com/urfave/cli/v2"
)

func main() {
	// EXAMPLE: Append to an existing template
	cli.AppHelpTemplate = fmt.Sprintf(`%s

WEBSITE: http://awesometown.example.com

SUPPORT: support@awesometown.example.com

`, cli.AppHelpTemplate)

	// EXAMPLE: Override a template
	cli.AppHelpTemplate = `NAME:
   {{.Name}} - {{.Usage}}
USAGE:
   {{.HelpName}} {{if .VisibleFlags}}[global options]{{end}}{{if .Commands}} command [command options]{{end}} {{if .ArgsUsage}}{{.ArgsUsage}}{{else}}[arguments...]{{end}}
   {{if len .Authors}}
AUTHOR:
   {{range .Authors}}{{ . }}{{end}}
   {{end}}{{if .Commands}}
COMMANDS:
{{range .Commands}}{{if not .HideHelp}}   {{join .Names ", "}}{{ "\t"}}{{.Usage}}{{ "\n" }}{{end}}{{end}}{{end}}{{if .VisibleFlags}}
GLOBAL OPTIONS:
   {{range .VisibleFlags}}{{.}}
   {{end}}{{end}}{{if .Copyright }}
COPYRIGHT:
   {{.Copyright}}
   {{end}}{{if .Version}}
VERSION:
   {{.Version}}
   {{end}}
`

	// EXAMPLE: Replace the `HelpPrinter` func
	cli.HelpPrinter = func(w io.Writer, templ string, data interface{}) {
		fmt.Println("Ha HA.  I pwnd the help!!1")
	}

	(&cli.App{}).Run(os.Args)
}
```

The default flag may be customized to something other than `-h/--help` by
setting `cli.HelpFlag`, e.g.:

<!-- {
  "args": ["&#45;&#45halp"],
  "output": "haaaaalp.*HALP"
} -->
```go
package main

import (
	"os"

	"github.com/urfave/cli/v2"
)

func main() {
	cli.HelpFlag = &cli.BoolFlag{
		Name:    "haaaaalp",
		Aliases: []string{"halp"},
		Usage:   "HALP",
		EnvVars: []string{"SHOW_HALP", "HALPPLZ"},
	}

	(&cli.App{}).Run(os.Args)
}
```

<!-- docs/v3/path-and-walk.md @ c6f4cf7e9223793478cfcde9b8f135cc8f86e78f -->
---
tags:
  - v3
search:
  boost: 2
---

# Path and Walk

`Command.Path()` returns the list of command names from the root to the
current command. `Command.Walk()` visits a command and every subcommand
recursively, calling a function on each.

## Path

The `Path()` method returns `[]string` where each element is a `Command.Name`
starting from the root. `FullName()` is equivalent to
`strings.Join(cmd.Path(), " ")`.

<!-- {
  "output": "top mid bottom"
} -->
```go
package main

import (
	"context"
	"fmt"
	"strings"

	"github.com/urfave/cli/v3"
)

func main() {
	subSubCmd := &cli.Command{
		Name: "bottom",
		Action: func(ctx context.Context, c *cli.Command) error {
			fmt.Println(strings.Join(c.Path(), " "))
			return nil
		},
	}
	subCmd := &cli.Command{Name: "mid", Commands: []*cli.Command{subSubCmd}, Action: func(context.Context, *cli.Command) error { return nil }}
	cmd := &cli.Command{
		Name:     "top",
		Commands: []*cli.Command{subCmd},
	}

	cmd.Run(context.Background(), []string{"top", "mid", "bottom"})
}
```

```sh-session
$ go run .
top mid bottom
```

## Walk

`Walk()` traverses the command tree depth-first, visiting the command itself
first, then each subcommand recursively.

<!-- {
  "output": "top\nmid\nbottom"
} -->
```go
package main

import (
	"context"
	"fmt"

	"github.com/urfave/cli/v3"
)

func main() {
	subSubCmd := &cli.Command{Name: "bottom", Action: func(context.Context, *cli.Command) error { return nil }}
	subCmd := &cli.Command{Name: "mid", Commands: []*cli.Command{subSubCmd}, Action: func(context.Context, *cli.Command) error { return nil }}
	cmd := &cli.Command{
		Name: "top",
		Commands: []*cli.Command{subCmd},
		Action: func(ctx context.Context, c *cli.Command) error { return nil },
	}

	cmd.Walk(func(c *cli.Command) error {
		fmt.Println(c.Name)
		return nil
	})
}
```

```sh-session
$ go run .
top
mid
bottom
```

### Short-circuiting

Return a non-nil error from the walk function to stop traversal early.

<!-- {
  "output": "top\nmid"
} -->
```go
package main

import (
	"context"
	"errors"
	"fmt"

	"github.com/urfave/cli/v3"
)

func main() {
	subSubCmd := &cli.Command{Name: "bottom", Action: func(context.Context, *cli.Command) error { return nil }}
	subCmd := &cli.Command{Name: "mid", Commands: []*cli.Command{subSubCmd}, Action: func(context.Context, *cli.Command) error { return nil }}
	cmd := &cli.Command{
		Name: "top",
		Commands: []*cli.Command{subCmd},
		Action: func(ctx context.Context, c *cli.Command) error { return nil },
	}

	err := cmd.Walk(func(c *cli.Command) error {
		fmt.Println(c.Name)
		if c.Name == "mid" {
			return errors.New("stop")
		}
		return nil
	})
	fmt.Println(err)
}
```

```sh-session
$ go run .
top
mid
stop
```

## Relation to Lineage

[`Lineage()`](https://pkg.go.dev/github.com/urfave/cli/v3#Command.Lineage)
returns the command and all its ancestors as `[]*Command` (child first).
`Path()` is similar but returns only the command names as `[]string` (root
first). Use `Lineage()` when you need access to the ancestor `*Command`
values; use `Path()` when you only need the names.

<!-- docs/v3/examples/help/suggestions.md @ c6f4cf7e9223793478cfcde9b8f135cc8f86e78f -->
