	cmd := &cli.Command{
		Action: func(ctx context.Context, cmd *cli.Command) error {
			fmt.Printf("Number of args : %d\n", cmd.Args().Len())
			var out string
			for i := 0; i < cmd.Args().Len(); i++ {
				out = out + fmt.Sprintf(" %v", cmd.Args().Get(i))
			}
			fmt.Printf("Hello%v", out)
			return nil
		},
	}

	if err := cmd.Run(context.Background(), os...", "path": "docs/v3/examples/arguments/basics.md", "retrieval_provenance": {"blob_sha": "ddde3a4779ba18d920df5664fc44fe00e2adecd3", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 11, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "docs/v3/examples/arguments/basics.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 4, "selection_score": [45, 4, 5, 5, "docs/v3/examples/arguments/basics.md"], "tree_discovery_succeeded": true, "tree_ref": "4937c163f8e8bd88fdb06c4eab67cde61436c205", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "4937c163f8e8bd88fdb06c4eab67cde61436c205"}, {"blob_sha": "96f35653598c4b5c71f7c728f21631c328150a91", "excerpt": "---
