COMMANDS:
{{range .Commands}}{{if not .HideHelp}}   {{join .Names ", "}}{{ "\t"}}{{.Usage}}{{ "\n" }}{{end}}{{end}}{{end}}{{if .VisibleFlags}}
GLOBAL OPTIONS:
   {{range .VisibleFlags}}{{.}}
   {{end}}{{end}}{{...", "path": "docs/v2/examples/generated-help-text.md", "retrieval_provenance": {"blob_sha": "f733b96b50a0a583ae1e8dadfe06d863047c23bd", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 11, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "docs/v2/examples/generated-help-text.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 5, "selection_score": [45, 5, 5, 4, "docs/v2/examples/generated-help-text.md"], "tree_discovery_succeeded": true, "tree_ref": "c5f123b3909fb3270433574d9940650579cf9820", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "c5f123b3909fb3270433574d9940650579cf9820"}, {"blob_sha": "610539b38e542b0a1672167bb922ccb62c23dbe6", "excerpt": "---
