	subCmd := &cli.Command{Name: "mid", Commands: [...", "path": "docs/v3/path-and-walk.md", "retrieval_provenance": {"blob_sha": "8054860ef052a0d79de51ede5886c113102a9f1b", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 11, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "docs/v3/path-and-walk.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 3, "selection_score": [45, 4, 5, 3, "docs/v3/path-and-walk.md"], "tree_discovery_succeeded": true, "tree_ref": "02bdfb095e7c87878040716efe62e50efafbf158", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "02bdfb095e7c87878040716efe62e50efafbf158"}, {"blob_sha": "e5a5fff7e5c556c07c1e99e23175e3949a3d7963", "excerpt": "---
