	subSubCmd := &cli.Command{Name: "bottom", Action: func(context.Context, *cli.Command) error {...", "path": "docs/v3/path-and-walk.md", "retrieval_provenance": {"blob_sha": "2117e4210e7e2e9bdb0f798c9ba63290db2d4fd0", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 11, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "docs/v3/path-and-walk.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 11, "selection_score": [45, 3, 5, 3, "docs/v3/path-and-walk.md"], "tree_discovery_succeeded": true, "tree_ref": "213b98c817bf5531f8c1eec4d7d1f7bf3c423a97", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "213b98c817bf5531f8c1eec4d7d1f7bf3c423a97"}, {"blob_sha": "7ab3da9a553ecb06ba0a57654c0db744e56a3604", "excerpt": "---
