The [Basics] showed how to access arguments for a command. They are all retrieved as strings which is fine
but it we need to say get integers or timestamps the user would have to convert from string to desired type. 
To ease the burden on users the `cli` library offers predefined `{Type}Arg` and `{Type}Args` structure to facilitate this.
The value of the argument can be retrieved using the `command.{Type}Arg()` function. For e.g

<!-- {
  "args" : ["10"],
  "output": "We got 10"
} -->
```go
package main

import (
	"fmt"
	"log"
	"os"
	"context"

	"github.com/urfave/cli/v3"
)

func main() {
	cmd := &cli.Command{
		Arguments: []cli.Argument{
			&cli.IntArg{
				Name: "someint",
			},
		},
		Action: func(ctx context.Context, cmd *cli.Command) error {
			fmt.Printf("We got %d", cmd.IntArg("someint"))
			return nil
		},
	}

	if err := cmd.Run(context.Background(), os.Args); err != nil {
		log.Fatal(err)
	}
}
```

Running this program with an argument gives the following output

```sh-session
$ greet 10
We got 10
```

Instead of using the `cmd.{Type}Arg()` function to retrieve the argument value a destination for the argument can be set
for e.g

<!-- {
  "args" : ["25"],
  "output": "We got 25"
} -->
```go
package main

import (
	"fmt"
	"log"
	"os"
	"context"

	"github.com/urfave/cli/v3"
)

func main() {
	var ival int
	cmd := &cli.Command{
		Arguments: []cli.Argument{
			&cli.IntArg{
				Name: "someint",
				Destination: &ival,
			},
		},...", "path": "docs/v3/examples/arguments/advanced.md", "retrieval_provenance": {"blob_sha": "7ab3da9a553ecb06ba0a57654c0db744e56a3604", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 11, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "docs/v3/examples/arguments/advanced.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 12, "selection_score": [45, 2, 5, 5, "docs/v3/examples/arguments/advanced.md"], "tree_discovery_succeeded": true, "tree_ref": "213b98c817bf5531f8c1eec4d7d1f7bf3c423a97", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "213b98c817bf5531f8c1eec4d7d1f7bf3c423a97"}]}

