Lets add some arguments to our greeter app. This allows you to change the behaviour of
the app depending on what argument has been passed. You can lookup arguments by calling 
the `Args` function on `cli.Command`, e.g.:

<!-- {
  "args" : ["Friend"],
  "output": "Hello \"Friend\""
} -->
```go
package main

import (
	"fmt"
	"log"
	"os"
	"context"

	"github.com/urfave/cli/v3"
)

func main() {
	cmd := &cli.Command{
		Action: func(ctx context.Context, cmd *cli.Command) error {
			fmt.Printf("Hello %q", cmd.Args().Get(0))
			return nil
		},
	}

	if err := cmd.Run(context.Background(), os.Args); err != nil {
		log.Fatal(err)
	}
}
```

Running this program with an argument gives the following output

```sh-session
$ greet friend
Hello "Friend"
```

Any number of arguments can be passed to the greeter app. We can get the number of arguments
and each argument using the `Args`

<!-- {
  "args" : ["Friend", "1", "bar", "2.0"],
  "output": "Number of args : 4\nHello Friend 1 bar 2.0"
} -->
```go
package main

import (
	"fmt"
	"log"
	"os"
	"context"

	"github.com/urfave/cli/v3"
)

func main() {
	cmd := &cli.Command{
		Action: func(ctx context.Context, cmd *cli.Command) error {
			fmt.Printf("Number of args : %d\n", cmd.Args().Len())
			var out string
			for i := 0; i < cmd.Args().Len(); i++ {
				out = out + fmt.Sprintf(" %v", cmd.Args().Get(i))
			}
			fmt.Printf("Hello%v", out)
			return nil
		},
	}

	if err := cmd.Run(context.Background(), os...", "path": "docs/v3/examples/arguments/basics.md", "retrieval_provenance": {"blob_sha": "ddde3a4779ba18d920df5664fc44fe00e2adecd3", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 11, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "docs/v3/examples/arguments/basics.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 8, "selection_score": [45, 3, 5, 5, "docs/v3/examples/arguments/basics.md"], "tree_discovery_succeeded": true, "tree_ref": "57943ed4620868d3f58583a1fd3ae5b0367b25ae", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "57943ed4620868d3f58583a1fd3ae5b0367b25ae"}, {"blob_sha": "8c4137e598eee8ac91e15aa38ab75775805f2ad9", "excerpt": "---
