	var language string

	app := &cli.App{
		Flags: []cli.Flag{
			&cli.StringFlag{
				Name:        "lang",
				Value:       "english",
				Usage:       "language for the greeting",
				Destination: &language,
			},
		},
		Action: func(cCtx *cli.Context) error {
			name := "someone"
			if cCtx.NArg() > 0 {
				name = cCtx.Args().Get(0)
			}
			if language == "spanish" {
				fmt.Println("Hola", name)
			} el...", "path": "docs/v2/examples/flags.md", "retrieval_provenance": {"blob_sha": "2f16c4c3e85805b545708cfacb919a8744c37b2b", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 11, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "docs/v2/examples/flags.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 11, "selection_score": [45, 3, 5, 4, "docs/v2/examples/flags.md"], "tree_discovery_succeeded": true, "tree_ref": "57943ed4620868d3f58583a1fd3ae5b0367b25ae", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "57943ed4620868d3f58583a1fd3ae5b0367b25ae"}, {"blob_sha": "f733b96b50a0a583ae1e8dadfe06d863047c23bd", "excerpt": "---
