The urfave/cli v3 library supports programmable completion for apps utilizing its framework. This means
that the completion is generated dynamically at runtime by invoking the app itself with a special hidden
flag. The urfave/cli searches for this flag and activates a different flow for command paths than regular flow
The following shells are supported

 - bash
 - zsh
 - fish
 - powershell

Enabling auto complete requires 2 things

 - Setting the `EnableShellCompletion` field on root `Command` object to `true`. 
 - Sourcing the completion script for that particular shell. 

The completion script for a particular shell can be retrieved by running the "completion" subcommand
on the app after the `EnableShellCompletion` field on root `Command` object has been set to `true`. 

Consider the following program

```go
package main

import (
	"fmt"
	"log"
	"os"
	"context"

	"github.com/urfave/cli/v3"
)

func main() {
	cmd := &cli.Command{
		Name: "greet",
		EnableShellCompletion: true,
		Commands: []*cli.Command{
			{
				Name:    "add",
				Aliases: []string{"a"},
				Usage:   "add a task to the list",
				Action: func(ctx context.Context, cmd *cli.Command) error {
					fmt.Println("added task: ", cmd.Args().First())
					return nil
				},
			},
			{
				Name:    "complete",
				Aliases: []string{"c"},
				Usage:   "complete a task on the list",
				Action: func(ctx context.Context, cmd *cli.Command) error {
					fmt.Println("completed task...", "path": "docs/v3/examples/completions/shell-completions.md", "retrieval_provenance": {"blob_sha": "8c4137e598eee8ac91e15aa38ab75775805f2ad9", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 11, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "docs/v3/examples/completions/shell-completions.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 4, "selection_score": [45, 2, 5, 5, "docs/v3/examples/completions/shell-completions.md"], "tree_discovery_succeeded": true, "tree_ref": "0ad38592ac44f2245175f1324bdb4288b5937797", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "0ad38592ac44f2245175f1324bdb4288b5937797"}, {"blob_sha": "e5a5fff7e5c556c07c1e99e23175e3949a3d7963", "excerpt": "---
