import (
	"log"
	"os"
	"context"

	"github.com/urfave/cli/v3"
)

func main() {
	cmd := &cli.Command{
		Flags: []cli.Flag{
			&cli.StringFla...", "path": "docs/v3/examples/flags/value-sources.md", "retrieval_provenance": {"blob_sha": "f9d588db7a5201a5f5bf63f6a5396edd6e3f26ad", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 11, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "docs/v3/examples/flags/value-sources.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 2, "selection_score": [45, 4, 5, 5, "docs/v3/examples/flags/value-sources.md"], "tree_discovery_succeeded": true, "tree_ref": "eb79f0545a47972c87c7c41b99d36fc5012423c9", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "eb79f0545a47972c87c7c41b99d36fc5012423c9"}, {"blob_sha": "dc089a16ae15e8b5bde90f76829607bb1c663a12", "excerpt": "---
