If default completion isn't sufficient additional customizations are available 

- custom auto-completion
- customizing completion command

#### Custom auto-completion
<!-- {
  "args": ["complete", "&#45;&#45;generate&#45;shell&#45;completion"],
  "output": "laundry"
} -->
```go
package main

import (
	"fmt"
	"log"
	"os"
	"context"

	"github.com/urfave/cli/v3"
)

func main() {
	tasks := []string{"cook", "clean", "laundry", "eat", "sleep", "code"}

	cmd := &cli.Command{
		EnableShellCompletion: true,
		Commands: []*cli.Command{
			{
				Name:    "complete",
				Aliases: []string{"c"},
				Usage:   "complete a task on the list",
				Action: func(ctx context.Context, cmd *cli.Command) error {
					fmt.Println("completed task: ", cmd.Args().First())
					return nil
				},
				ShellComplete: func(ctx context.Context, cmd *cli.Command) {
					// This will complete if no args are passed
					if cmd.NArg() > 0 {
						return
					}
					for _, t := range tasks {
						fmt.Println(t)
					}
				},
			},
		},
	}

	if err := cmd.Run(context.Background(), os.Args); err != nil {
		log.Fatal(err)
	}
}
```
![](../../images/custom-bash-autocomplete.gif)

#### Customize a completion command

By default, a completion command is hidden, meaning the command isn't included in the help message.
You can customize it by setting root Command's `ConfigureShellCompletionCommand`.

```go
package main

import (
	"context"
	"fmt"
	"log"
	"os"

	"github.com/urfav...", "path": "docs/v3/examples/completions/customizations.md", "retrieval_provenance": {"blob_sha": "183f3d82508a1132816817879fa86c3c23b0550a", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 11, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "docs/v3/examples/completions/customizations.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 2, "selection_score": [45, 3, 5, 5, "docs/v3/examples/completions/customizations.md"], "tree_discovery_succeeded": true, "tree_ref": "d525e78922331468649ed06f88834cc21a4296dd", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "d525e78922331468649ed06f88834cc21a4296dd"}, {"blob_sha": "73af176d8f3f1a4d405c64892a3efd7890ce4f59", "excerpt": "---
