	"fmt"
	"io"
	"os"
	"context"

	"github.com/urfave/cli/v3"
)

func main() {
	// EXAMPLE: Append to an existing template
	cli.RootCommandHelpTemplate = fmt.Sprintf(`%s

WEBSITE: http://awesometown.example.com

SUPPORT: support@awesometown.example.com

`, cli.RootCommandHelpTemplate)

	// EXAMPLE: Override a template
	cli.RootCommandHelpTemplate = `NAME:
   {{.Name}} - {{.Usage}}
USAGE:
   {{.HelpName}} {{if .VisibleFlags}}[global options]{{end}}{{if .Commands}} command [command options]{{end}} {{if .ArgsUsage}}{{.ArgsUsage}}{{else}}[arguments...]{{end}}
   {{if len .Authors}}
AUTHOR:
   {{range .Authors}}{{ . }}{{end}}
   {{end}}{{if .Commands}}
COMMANDS:
{{range .Commands}}{{if not .HideHelp}}   {{join .Names ", "}}{{ "\t"}}{{.Usage}}{{ "\n" }}{{end}}{{end}}{{end}}{{if .VisibleFlags}}
GLOBAL OPTIONS:
   {{rang...", "path": "docs/v3/examples/help/generated-help-text.md", "retrieval_provenance": {"blob_sha": "973a85756d4403a71d26d435e6d2ec373723a762", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 11, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "docs/v3/examples/help/generated-help-text.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 5, "selection_score": [45, 3, 5, 5, "docs/v3/examples/help/generated-help-text.md"], "tree_discovery_succeeded": true, "tree_ref": "b5aa7101bd66f4340bfd737fe4bf12496d625632", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "b5aa7101bd66f4340bfd737fe4bf12496d625632"}, {"blob_sha": "39965addb4fd95e7ebb5694bd5cd5930f137fdff", "excerpt": "---
