					fmt.Println("completed task...", "path": "docs/v3/examples/completions/shell-completions.md", "retrieval_provenance": {"blob_sha": "8c4137e598eee8ac91e15aa38ab75775805f2ad9", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 11, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "docs/v3/examples/completions/shell-completions.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 5, "selection_score": [45, 4, 5, 5, "docs/v3/examples/completions/shell-completions.md"], "tree_discovery_succeeded": true, "tree_ref": "a9261cf1832b278c1c195c91f9ee961f5fc9554e", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "a9261cf1832b278c1c195c91f9ee961f5fc9554e"}, {"blob_sha": "8af8197eeefaa6a6109eebdc99f62857931c2fc9", "excerpt": "---
